#include <stdio.h>
int q[1005], f=0, r=0; void push(int v) { q[r++]=v; } int pop() { return q[f++]; } int empty() { return f==r; }
int main() { int n, m, u, v, s; if(scanf("%d%d", &n, &m)!=2) return 0; int g[105][105]={0}, vis[105]={0}; for(int i=0; i<m; i++) { scanf("%d%d", &u, &v); if(u>=0 && u<n && v>=0 && v<n) { g[u][v]=1; g[v][u]=1; } } if(scanf("%d", &s)!=1) return 0; if(n==0 || s<0 || s>=n) { printf("\n"); return 0; } push(s); vis[s]=1; int first=1; while(!empty()) { int c=pop(); printf("%s%d", first?"":" ", c); first=0; for(int i=0; i<n; i++) { if(g[c][i] && !vis[i]) { vis[i]=1; push(i); } } } printf("\n"); return 0; }

#include <stdio.h>
int g[105][105], vis[105], n;
int first=1;
void dfs(int u) { vis[u]=1; printf("%s%d", first?"":" ", u); first=0; for(int i=0; i<n; i++) { if(g[u][i] && !vis[i]) dfs(i); } }
int main() { int m, u, v, s; if(scanf("%d%d", &n, &m)!=2) return 0; for(int i=0; i<105; i++) for(int j=0; j<105; j++) g[i][j]=0; for(int i=0; i<105; i++) vis[i]=0; for(int i=0; i<m; i++) { scanf("%d%d", &u, &v); if(u>=0 && u<n && v>=0 && v<n) { g[u][v]=1; g[v][u]=1; } } if(scanf("%d", &s)!=1) return 0; if(n==0 || s<0 || s>=n) { printf("\n"); return 0; } dfs(s); printf("\n"); return 0; }
